        elif route == "invalid_key":
            self._send_error(400, "invalid key")
        else:
            self._send_error(404, "route not found")

    def do_PUT(self) -> None:
        route, key = self._route()
        if route == "invalid_key":
            self._send_error(400, "invalid key")
            return
        if route != "key":
            self._send_error(404, "route not found")
            return
