            return False, None
        content_length = self.headers.get("Content-Length")
        if content_length is None:
            self._send_error(411, "Content-Length is required")
            return False, None
        try:
            length = int(content_length)
        except ValueError:
            self._send_error(400, "invalid Content-Length")
            return False, None
        if length < 0:
            self._send_error(400, "invalid Content-Length")
            return False, None
